`timescale 1ns/1ps
// Self-checking testbench - generated by scripts/make_experiments.py
// One clock = one model step. Writes qif_neuron.csv in the simulator's working directory.
module tb;
    reg clk = 0, rst = 1, en = 1;
    always #5 clk = ~clk;
    integer t, f, errors = 0;
    task check(input [8*24-1:0] what, input integer got, input integer exp);
        begin
            if (exp >= 0 && got !== exp) begin errors = errors + 1; $display("  FAIL %0s: got %0d, expected %0d", what, got, exp); end
            else $display("  ok   %0s = %0d", what, got);
            $display("RESULT %0s=%0d", what, got);
        end
    endtask
    reg signed [31:0] i_in;  wire signed [31:0] v;  wire spike;
    qif_neuron dut (.clk(clk), .rst(rst), .en(en), .i_in(i_in), .v(v), .spike(spike));
    integer n5 = 0, n7 = 0, n12 = 0;
    initial begin
        f = $fopen("qif_neuron.csv", "w"); $fdisplay(f, "t,i,v,spike");
        i_in = 0; repeat (2) @(posedge clk); #1 rst = 0;
        for (t = 0; t < 400; t = t + 1) begin
            i_in = (t < 20) ? 0 : (t < 140) ? 5*256 : (t < 270) ? 7*256 : 12*256;
            @(posedge clk); #1;
            if (t < 140) n5 = n5 + spike; else if (t < 270) n7 = n7 + spike; else n12 = n12 + spike;
            $fdisplay(f, "%0d,%0d,%0d,%0d", t, i_in, v, spike);
        end
        check("spikes_at_5mV", n5, 0);
        check("spikes_at_7mV", n7, 2);
        check("spikes_at_12mV", n12, 8);
        if (errors == 0) $display("*** PASS ***"); else $display("*** FAIL: %0d check(s) ***", errors);
        $fclose(f); $finish;
    end
endmodule
